-- FORK BOMB: a bomb-maze game for the Solana Breakpoint 2026 badge.
-- Blow up forks, dodge the rugs, reach the Finality gate.
-- Art lives in art.lua (generated by tools/art.py).

local A = require("art")

local T = 16                  -- tile size in pixels
local COLS, ROWS = 15, 13     -- map size in tiles (240 x 208)
local MX, MY = 0, 5           -- map position on screen
local HX = 246                -- HUD column
local FUSE = 2.4              -- seconds before a bomb goes off
local FLAME_T = 0.5           -- seconds a flame burns
local BREAK_T = 0.45          -- seconds a block takes to break
local STAGE_TIME = 200        -- seconds per stage
local BG = 0x0B0A14

local floor, abs, min, max = math.floor, math.abs, math.min, math.max
local random = math.random

-- ------------------------------------------------------------------ stages
local STAGES = {
  {w = 1, layout = "classic", density = 0.30, foes = {"rug", "rug", "rug"}, pu = "fire"},
  {w = 1, layout = "logo",    density = 0.34, foes = {"rug", "rug", "jeet", "jeet"}, pu = "bomb"},
  {w = 2, layout = "open",    density = 0.40, foes = {"jeet", "jeet", "sand", "rug", "rug"}, pu = "speed"},
  {w = 2, layout = "logo",    density = 0.40, foes = {"jeet", "jeet", "jeet", "sand", "sand"}, pu = "fire"},
  {w = 3, layout = "classic", density = 0.42, foes = {"sand", "sand", "fud", "jeet", "rug"}, pu = "bomb"},
  {w = 3, layout = "logo",    density = 0.42, foes = {"sand", "sand", "sand", "fud", "fud"}, pu = "shield"},
  {w = 4, layout = "open",    density = 0.46, foes = {"rug", "jeet", "jeet", "sand", "sand", "fud"}, pu = "fire"},
  {w = 4, layout = "logo",    density = 0.45, foes = {"jeet", "jeet", "sand", "sand", "sand", "fud", "fud", "fud"}, pu = "speed"},
}

local FOES = {
  rug  = {speed = 26, score = 100, name = "RUG"},
  jeet = {speed = 50, score = 200, name = "JEET"},
  sand = {speed = 38, score = 400, name = "SANDWICH"},
  fud  = {speed = 30, score = 800, name = "FUD", ghost = true},
}

local PU_TEXT = {
  bomb = "+1 BOMB",
  fire = "+1 RANGE",
  speed = "IBRL! SPEED UP",
  shield = "SHIELD 10s",
}

-- ------------------------------------------------------------------ images
local IMG = {}
local loaded_world = 0

local function palette_for(w)
  local p = {}
  for k, v in pairs(A.pal) do p[k] = v end
  local W = A.worlds[w]
  p.F, p.E, p.B, p.L, p.D = W.F, W.E, W.B, W.L, W.D
  return p
end

-- Sprites that use world colours (F E B L D) are reloaded on a world change.
local WORLD_SPRITES = {}
for name, rows in pairs(A.s) do
  for _, r in ipairs(rows) do
    if r:find("[FEBLD]") then WORLD_SPRITES[name] = true break end
  end
end

local function load_world(w)
  if loaded_world == w then return end
  local pal = palette_for(w)
  for name, rows in pairs(A.s) do
    if loaded_world == 0 or WORLD_SPRITES[name] then
      IMG[name] = ui.load(rows, {palette = pal})
    end
  end
  loaded_world = w
end

-- ------------------------------------------------------------------ LEDs
local has_led = led ~= nil
local led_now = {}
local led_flash = 0
local led_flash_col = 0

local function leds_off()
  if has_led then led.off() end
  led_now = {}
end

-- only touch an LED when its colour changes
local function led_put(n, col)
  if led_now[n] ~= col then led_now[n] = col led.hex(n, col) end
end

local function flash(col, t)
  led_flash, led_flash_col = t or 0.15, col
end

-- ------------------------------------------------------------------ save
local function int_or(v, lo, hi, def)
  if type(v) ~= "number" or v ~= v or v < lo or v > hi then return def end
  return floor(v)
end

local save = {
  best = int_or(storage.get("best"), 0, 2000000000, 0),
  stage = int_or(storage.get("stage"), 1, 8, 1),
  epoch = int_or(storage.get("epoch"), 1, 999, 1),
}

local function persist()
  storage.set("best", save.best)
  storage.set("stage", save.stage)
  storage.set("epoch", save.epoch)
end

-- ------------------------------------------------------------------ !LAMP rewards
-- Once per day each: 1 for the first clear of each stage (max 8), 5 for finishing an
-- epoch (stage 4-2), 2 for a new best score. At most 15 a day; replays earn nothing.
-- The server's award cap is the real limit; this only keeps the app from asking twice.
local LAMP_STAGE, LAMP_EPOCH, LAMP_BEST = 1, 5, 2
local needs_x = false            -- the server said "link X first": stop asking this session
local lamp_pending = {}          -- awards asked for and not answered yet (this session only)
local lamp_session = {}          -- what this session already got, for badges without a clock

local function today()
  local t = sys.time and sys.time()
  if not t then return nil end
  return floor(t / 86400)
end

local function lamp_log()
  local d = today()
  if not d then return nil end
  local log = storage.get("lamps")
  if type(log) ~= "table" or log.day ~= d then log = {day = d, got = {}} end
  if type(log.got) ~= "table" then log.got = {} end
  return log
end

-- key: "s3" (stage 3), "epoch" or "best".
local function award(key, amount, reason)
  if not lamps or not lamps.award or needs_x then return end
  local log = lamp_log()       -- nil when the badge has no clock yet: the session guards it
  local day = log and log.day
  local skey = key .. "@" .. tostring(day)
  if (log and log.got[key]) or lamp_session[skey] or lamp_pending[key] then return end
  lamp_pending[key] = true
  lamps.award(amount, reason, function(ok, r)
    lamp_pending[key] = nil
    if ok and type(r) == "table" and r.needsX then
      -- not linked yet: say so once and stop asking until the next launch
      needs_x = true
      ui.toast("Link X in My Badge to earn !LAMPs")
      return
    end
    if not ok then return end      -- offline or busy: ask again next time
    lamp_session[skey] = true      -- paid, or the daily cap is used up
    if type(r) == "table" and (r.awarded or 0) > 0 then
      ui.toast("+" .. r.awarded .. " !LAMP" .. (r.awarded > 1 and "s" or "") .. "  " .. reason)
    end
    local now = lamp_log()
    if now and now.day == day then -- an answer after midnight does not use up the new day
      now.got[key] = true
      storage.set("lamps", now)
    end
  end)
end

-- ------------------------------------------------------------------ game state
local scene = "title"
local run = nil        -- {stage, epoch, score, lives, bombs, fire, speed}
local G = nil          -- the current stage

local function idx(c, r) return r * COLS + c end

-- "1-2", or "2:1-2" from the second epoch on
local function stage_name(stage, epoch)
  local st = STAGES[stage]
  return (epoch > 1 and (epoch .. ":") or "") .. st.w .. "-" .. ((stage - 1) % 2 + 1)
end

-- grid codes
local FLOOR, WALL, BLOCK, BAR = 0, 1, 2, 3

-- ------------------------------------------------------------------ UI helpers
local canvas
local hud = {}
local popups = {}
local overlay = {}

local function clear_overlay()
  for _, o in ipairs(overlay) do o:remove() end
  overlay = {}
end

local function center_label(y, text, size, color)
  local l = ui.label(0, y, text, {size = size or 14, color = color or "text", w = ui.W, align = "center"})
  overlay[#overlay + 1] = l
  return l
end

-- ------------------------------------------------------------------ map building
local function build_map(st)
  local g = {}
  local deco = {}
  for r = 0, ROWS - 1 do
    for c = 0, COLS - 1 do
      local t = FLOOR
      if r == 0 or c == 0 or r == ROWS - 1 or c == COLS - 1 then
        t = WALL
      elseif st.layout == "open" then
        if r % 2 == 0 and c % 4 == 2 then t = WALL end
        if r % 4 == 0 and c % 2 == 0 then t = WALL end
      elseif c % 2 == 0 and r % 2 == 0 then
        t = WALL
      end
      g[idx(c, r)] = t
    end
  end
  if st.layout == "logo" then
    -- the three Solana bars in the middle of the map
    for r = 3, 9 do
      for c = 3, 11 do
        if g[idx(c, r)] == WALL then g[idx(c, r)] = FLOOR end
      end
    end
    local bars = {{4, "1"}, {6, "2"}, {8, "3"}}
    for _, b in ipairs(bars) do
      local r, n = b[1], b[2]
      for c = 4, 10 do
        g[idx(c, r)] = BAR
        local part = (c == 4) and "l" or (c == 10) and "r" or "c"
        deco[idx(c, r)] = "bar" .. n .. part
      end
    end
  end
  -- fork blocks
  local blocks = {}
  for r = 1, ROWS - 2 do
    for c = 1, COLS - 2 do
      local i = idx(c, r)
      local safe = (c + r) <= 3
      if g[i] == FLOOR and not safe and random() < st.density then
        g[i] = BLOCK
        blocks[#blocks + 1] = i
      end
    end
  end
  -- the gate and the power-up need two blocks: force them if the dice said no
  local r = ROWS - 2
  for c = COLS - 2, 1, -1 do
    if #blocks >= 2 then break end
    local i = idx(c, r)
    if g[i] == FLOOR then g[i] = BLOCK blocks[#blocks + 1] = i end
  end
  return g, deco, blocks
end

local function passable_tile(c, r, ghost)
  if c < 0 or r < 0 or c >= COLS or r >= ROWS then return false end
  local t = G.grid[idx(c, r)]
  if t == FLOOR then return true end
  if t == BLOCK and ghost and c > 0 and r > 0 and c < COLS - 1 and r < ROWS - 1 then return true end
  return false
end

-- ------------------------------------------------------------------ drawing the map
local function tile_sig(i)
  local t = G.grid[i]
  local base
  if t == WALL then base = "wall"
  elseif t == BAR then base = G.deco[i]
  elseif t == BLOCK then
    local b = G.breaking[i]
    if b then
      local k = BREAK_T - b
      base = k < 0.15 and "break1" or k < 0.3 and "break2" or "break3"
    else
      base = "block"
    end
  else base = "floor" end
  local over = ""
  local f = G.flames[i]
  if f then
    local age = FLAME_T - f.t
    local s = age < 0.07 and 2 or age < 0.33 and 3 or age < 0.42 and 2 or 1
    over = "fire_" .. f.kind .. s
  elseif G.bombs[i] then
    local b = G.bombs[i]
    local ph = floor((FUSE - b.t) * (b.t < 0.8 and 10 or 5)) % 3
    over = "bomb" .. (ph + 1)
  elseif t ~= BLOCK then
    local it = G.items[i]
    if it then
      local blink = floor(G.clock * 4) % 2 + 1
      if it == "gate" then
        if G.open then over = "gate" .. (floor(G.clock * 8) % 3 + 1) else over = "gate0" end
      else
        over = "pu_" .. it .. blink
      end
    end
  end
  if t == BLOCK and G.breaking[i] then
    -- falling pieces over the floor
    return "floor", base
  end
  return base, over
end

local function draw_tile(i)
  local base, over = tile_sig(i)
  local d = G.drawn[i]
  if d and d[1] == base and d[2] == over then return end
  if d then d[1], d[2] = base, over else G.drawn[i] = {base, over} end
  local x, y = (i % COLS) * T, (i // COLS) * T
  if base ~= "floor" and base ~= "wall" and base ~= "block" then
    canvas:image(IMG.floor, x, y)   -- bars have see-through corners
  end
  canvas:image(IMG[base], x, y)
  if over ~= "" then canvas:image(IMG[over], x, y) end
end

local function touch(i) G.touched[i] = true end

local function redraw_dirty()
  for i in pairs(G.touched) do draw_tile(i) end
  G.touched = {}
  for i in pairs(G.bombs) do draw_tile(i) end
  for i in pairs(G.flames) do draw_tile(i) end
  for i in pairs(G.breaking) do draw_tile(i) end
  for i in pairs(G.items) do
    if G.grid[i] ~= BLOCK then draw_tile(i) end
  end
end

-- ------------------------------------------------------------------ HUD
local function hud_build(st)
  local W = A.worlds[st.w]
  hud.stage_t = ui.label(HX, 2, "STAGE", {size = 12, color = "dim"})
  hud.stage = ui.label(HX, 14, "", {size = 20, color = "text"})
  hud.world = ui.label(HX, 38, W.name, {size = 12, color = W.L})
  hud.score_t = ui.label(HX, 56, "SCORE", {size = 12, color = "dim"})
  hud.score = ui.label(HX, 68, "0", {size = 14, color = "text"})
  local rows = {
    {"i_clock", "time"}, {"i_life", "lives"}, {"i_bomb", "bombs"},
    {"i_fire", "fire"}, {"i_speed", "speed"}, {"i_shield", "shield"},
  }
  for n, row in ipairs(rows) do
    local y = 90 + (n - 1) * 20
    hud["ic_" .. row[2]] = ui.image(HX, y, IMG[row[1]], {scale = 2})
    hud[row[2]] = ui.label(HX + 22, y + 1, "", {size = 14, color = "text"})
  end
end

local last_hud = {}
local function hud_set(key, text, color)
  if last_hud[key] == text then return end
  last_hud[key] = text
  hud[key]:text(text)
  if color then hud[key]:color(color) end
end

local function hud_update()
  hud_set("stage", stage_name(run.stage, run.epoch))
  hud_set("score", tostring(run.score))
  local t = max(0, floor(G.time))
  hud_set("time", tostring(t), t <= 30 and "orange" or "text")
  hud_set("lives", "x" .. run.lives)
  hud_set("bombs", "x" .. run.bombs)
  hud_set("fire", "x" .. run.fire)
  hud_set("speed", "x" .. run.speed)
  local sh = G.player.shield
  local on = sh > 0
  if last_hud.sh_on ~= on then
    last_hud.sh_on = on
    hud.ic_shield:show(on)
    hud.shield:show(on)
  end
  if on then hud_set("shield", tostring(math.ceil(sh)) .. "s", "green") end
end

-- ------------------------------------------------------------------ score popups
local function popup(x, y, text)
  if #popups >= 4 then
    popups[1].l:remove()
    table.remove(popups, 1)
  end
  local l = ui.label(MX + x - 8, MY + y, text, {size = 12, color = "yellow"})
  popups[#popups + 1] = {l = l, t = 0.8, x = MX + x - 8, y = MY + y}
end

local function update_popups(dt)
  for k = #popups, 1, -1 do
    local p = popups[k]
    p.t = p.t - dt
    p.y = p.y - dt * 20
    if p.t <= 0 then
      p.l:remove()
      table.remove(popups, k)
    else
      p.l:pos(floor(p.x), floor(p.y))
    end
  end
end

local function clear_popups()
  for _, p in ipairs(popups) do p.l:remove() end
  popups = {}
end

-- ------------------------------------------------------------------ entities
local DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}}

local function ent_tile(e)
  return floor((e.x + 8) / T), floor((e.y + 8) / T)
end

local function make_foe(kind, c, r)
  local def = FOES[kind]
  local e = {
    kind = kind, x = c * T, y = r * T, tc = c, tr = r, dx = 0, dy = 0,
    speed = def.speed * (1 + 0.15 * (run.epoch - 1)),
    ghost = def.ghost, alive = true, dying = 0, anim = random() * 2,
  }
  e.img = ui.image(MX + e.x, MY + e.y, IMG[kind .. "1"])
  G.foes[#G.foes + 1] = e
  return e
end

local function foe_can(e, c, r)
  if not passable_tile(c, r, e.ghost) then return false end
  if G.bombs[idx(c, r)] then return false end
  return true
end

local function sees_player(e, range)
  local pc, pr = ent_tile(G.player)
  if pc ~= e.tc and pr ~= e.tr then return nil end
  local dx = pc > e.tc and 1 or pc < e.tc and -1 or 0
  local dy = pr > e.tr and 1 or pr < e.tr and -1 or 0
  local c, r = e.tc, e.tr
  for _ = 1, range do
    if c == pc and r == pr then return dx, dy end
    c, r = c + dx, r + dy
    if not foe_can(e, c, r) then return nil end
  end
  if c == pc and r == pr then return dx, dy end
  return nil
end

local function choose_dir(e)
  local opts = {}
  for _, d in ipairs(DIRS) do
    if foe_can(e, e.tc + d[1], e.tr + d[2]) then opts[#opts + 1] = d end
  end
  if #opts == 0 then e.dx, e.dy = 0, 0 return end
  local function keep()
    return (e.dx ~= 0 or e.dy ~= 0) and foe_can(e, e.tc + e.dx, e.tr + e.dy)
  end
  local function pick()
    -- avoid turning straight back when there is another way
    if #opts > 1 then
      local o2 = {}
      for _, d in ipairs(opts) do
        if not (d[1] == -e.dx and d[2] == -e.dy) then o2[#o2 + 1] = d end
      end
      if #o2 > 0 then opts = o2 end
    end
    local d = opts[random(#opts)]
    e.dx, e.dy = d[1], d[2]
  end
  if e.kind == "rug" then
    if keep() and random() > 0.15 then return end
    pick()
  elseif e.kind == "jeet" then
    if keep() and random() > 0.5 then return end
    pick()
  elseif e.kind == "sand" then
    local dx, dy = sees_player(e, 6)
    if dx and foe_can(e, e.tc + dx, e.tr + dy) then e.dx, e.dy = dx, dy e.chasing = true return end
    e.chasing = false
    if keep() and random() > 0.25 then return end
    pick()
  elseif e.kind == "fud" then
    local pc, pr = ent_tile(G.player)
    if random() < 0.55 then
      local best, bd = nil, 999
      for _, d in ipairs(opts) do
        local dd = abs(e.tc + d[1] - pc) + abs(e.tr + d[2] - pr)
        if dd < bd then best, bd = d, dd end
      end
      e.dx, e.dy = best[1], best[2]
      return
    end
    if keep() and random() > 0.3 then return end
    pick()
  end
end

local function update_foe(e, dt)
  e.anim = e.anim + dt
  if not e.alive then
    e.dying = e.dying + dt
    if e.dying < 0.3 then
      e.img:set(IMG[e.kind .. "_x1"])
    elseif e.dying < 0.6 then
      e.img:set(IMG[e.kind .. "_x2"])
    elseif e.dying < 0.85 then
      e.img:set(IMG.puff)
    else
      e.img:remove()
      e.gone = true
    end
    return
  end
  local spd = e.speed * (e.chasing and 1.3 or 1)
  local dist = spd * dt
  local guard = 0
  while dist > 0 and guard < 4 do
    guard = guard + 1
    local tx, ty = e.tc * T, e.tr * T
    if e.x == tx and e.y == ty then
      choose_dir(e)
      if e.dx == 0 and e.dy == 0 then break end
      e.tc, e.tr = e.tc + e.dx, e.tr + e.dy
      tx, ty = e.tc * T, e.tr * T
    elseif G.bombs[idx(e.tc, e.tr)] and not (e.x == tx and e.y == ty) then
      -- a bomb appeared on the tile it was heading to: turn back
      e.tc, e.tr = e.tc - e.dx, e.tr - e.dy
      e.dx, e.dy = -e.dx, -e.dy
      tx, ty = e.tc * T, e.tr * T
    end
    local ddx, ddy = tx - e.x, ty - e.y
    local d = abs(ddx) + abs(ddy)
    if d <= dist then
      e.x, e.y = tx, ty
      dist = dist - d
    else
      if ddx ~= 0 then e.x = e.x + (ddx > 0 and dist or -dist) end
      if ddy ~= 0 then e.y = e.y + (ddy > 0 and dist or -dist) end
      dist = 0
    end
  end
  local fr = floor(e.anim * (e.kind == "jeet" and 8 or 4)) % 2 + 1
  if e.fr ~= fr then e.fr = fr e.img:set(IMG[e.kind .. fr]) end
  e.img:pos(MX + floor(e.x), MY + floor(e.y))
end

-- ------------------------------------------------------------------ player
local function make_player()
  local p = {x = T, y = T, dir = "d", walk = 0, alive = true, dying = 0, shield = 0, want = nil}
  p.img = ui.image(MX + p.x, MY + p.y, IMG.hero_d0)
  return p
end

local function player_can(c, r)
  if not passable_tile(c, r, false) then return false end
  local b = G.bombs[idx(c, r)]
  if b and not b.pass then return false end
  return true
end

local function move_axis(p, dx, dy, dist)
  local cx, cy = p.x + 8, p.y + 8
  local tc, tr = floor(cx / T), floor(cy / T)
  local ccx, ccy = tc * T + 8, tr * T + 8
  if dx ~= 0 then
    if cy ~= ccy then
      if player_can(tc + dx, tr) then
        local d = min(dist, abs(cy - ccy))
        cy = cy + (ccy > cy and d or -d)
        dist = dist - d
      else
        -- corner assist: lean into the next row if that way is open
        local nr = cy < ccy and tr - 1 or tr + 1
        if abs(cy - ccy) >= 4 and player_can(tc + dx, nr) and player_can(tc, nr) then
          local target = nr * T + 8
          local d = min(dist, abs(target - cy))
          cy = cy + (target > cy and d or -d)
        end
        p.x, p.y = cx - 8, cy - 8
        return
      end
    end
    if dist > 0 then
      local nx = cx + dx * dist
      if not player_can(tc + dx, tr) then
        if dx > 0 then nx = min(nx, ccx) else nx = max(nx, ccx) end
      end
      cx = nx
    end
  else
    if cx ~= ccx then
      if player_can(tc, tr + dy) then
        local d = min(dist, abs(cx - ccx))
        cx = cx + (ccx > cx and d or -d)
        dist = dist - d
      else
        local nc = cx < ccx and tc - 1 or tc + 1
        if abs(cx - ccx) >= 4 and player_can(nc, tr + dy) and player_can(nc, tr) then
          local target = nc * T + 8
          local d = min(dist, abs(target - cx))
          cx = cx + (target > cx and d or -d)
        end
        p.x, p.y = cx - 8, cy - 8
        return
      end
    end
    if dist > 0 then
      local ny = cy + dy * dist
      if not player_can(tc, tr + dy) then
        if dy > 0 then ny = min(ny, ccy) else ny = max(ny, ccy) end
      end
      cy = ny
    end
  end
  p.x, p.y = cx - 8, cy - 8
end

local KEYDIR = {left = {-1, 0, "l"}, right = {1, 0, "r"}, up = {0, -1, "u"}, down = {0, 1, "d"}}

local function kill_player(why)
  local p = G.player
  if not p.alive or G.cleared then return end
  p.alive = false
  p.dying = 0
  G.why = why
  flash(0xFF2040, 0.6)
end

local function update_player(dt)
  local p = G.player
  if not p.alive then
    p.dying = p.dying + dt
    local k = p.dying
    local f = k < 0.25 and "hero_x1" or k < 0.6 and "hero_x2" or k < 0.9 and "hero_x3" or k < 1.2 and "hero_x4" or nil
    if f then p.img:set(IMG[f]) else p.img:show(false) end
    return
  end
  if p.shield > 0 then
    p.shield = max(0, p.shield - dt)
    p.img:show(p.shield > 2 or floor(p.shield * 10) % 2 == 0)
  end
  local keys = sys.keys and sys.keys() or {}
  local k = nil
  if p.tap and p.tap > 0 then p.tap = p.tap - dt end
  if p.want and (keys[p.want] or (p.tap and p.tap > 0)) then k = p.want
  else
    for _, name in ipairs({"left", "right", "up", "down"}) do
      if keys[name] then k = name break end
    end
  end
  local moving = false
  if k then
    local d = KEYDIR[k]
    local speed = 46 + run.speed * 12
    local ox, oy = p.x, p.y
    move_axis(p, d[1], d[2], speed * dt)
    p.dir = d[3]
    moving = (p.x ~= ox or p.y ~= oy)
    if moving then p.walk = p.walk + abs(p.x - ox) + abs(p.y - oy) end
  end
  local fr = 0
  if moving then
    local seq = {1, 0, 2, 0}
    fr = seq[floor(p.walk / 5) % 4 + 1]
  end
  local name = "hero_" .. p.dir .. fr
  if p.frame ~= name then p.frame = name p.img:set(IMG[name]) end
  p.img:pos(MX + floor(p.x), MY + floor(p.y))
  -- bombs the player has stepped off become solid
  for i, b in pairs(G.bombs) do
    if b.pass then
      local bx, by = (i % COLS) * T, (i // COLS) * T
      if abs(p.x - bx) >= T or abs(p.y - by) >= T then b.pass = false end
    end
  end
end

-- ------------------------------------------------------------------ bombs and flames
local function place_bomb()
  local p = G.player
  if not p.alive or G.cleared or G.intro > 0 then return end
  if G.nbombs >= run.bombs then return end
  local c, r = ent_tile(p)
  local i = idx(c, r)
  if G.bombs[i] or G.grid[i] ~= FLOOR then return end
  G.bombs[i] = {t = FUSE, range = run.fire, pass = true}
  G.nbombs = G.nbombs + 1
  touch(i)
end

local function add_flame(i, kind)
  local f = G.flames[i]
  if f and f.kind ~= kind then
    local horiz = {h = true, el = true, er = true}
    local a, b = horiz[f.kind] or false, horiz[kind] or false
    if f.kind == "c" or kind == "c" or a ~= b then kind = "c" end
  end
  G.flames[i] = {t = FLAME_T, kind = kind, blast = f and f.blast or G.blast}
end

local function explode(i)
  local b = G.bombs[i]
  if not b then return end
  G.bombs[i] = nil
  G.nbombs = G.nbombs - 1
  G.blast = G.blast + 1
  G.blast_kills[G.blast] = 0
  add_flame(i, "c")
  flash(0x9945FF, 0.12)
  local c0, r0 = i % COLS, i // COLS
  local ends = {[1] = {"h", "er"}, [-1] = {"h", "el"}}
  local vends = {[1] = {"v", "ed"}, [-1] = {"v", "eu"}}
  for _, d in ipairs(DIRS) do
    for n = 1, b.range do
      local c, r = c0 + d[1] * n, r0 + d[2] * n
      local j = idx(c, r)
      local t = G.grid[j]
      if t == WALL or t == BAR or t == nil then break end
      if t == BLOCK then
        if not G.breaking[j] then G.breaking[j] = BREAK_T end
        break
      end
      if G.bombs[j] then
        G.bombs[j].t = min(G.bombs[j].t, 0.06)
        break
      end
      local it = G.items[j]
      if it and it ~= "gate" and not G.fresh[j] then
        G.items[j] = nil
        touch(j)
      elseif it == "gate" and G.gate_cool <= 0 then
        G.gate_cool = 3
        G.spawn_at_gate = 2
      end
      local pair = d[1] ~= 0 and ends[d[1]] or vends[d[2]]
      add_flame(j, n == b.range and pair[2] or pair[1])
    end
  end
end

local function update_bombs(dt)
  local due = {}
  for i, b in pairs(G.bombs) do
    b.t = b.t - dt
    if b.t <= 0 then due[#due + 1] = i end
  end
  for _, i in ipairs(due) do explode(i) end
  for i, f in pairs(G.flames) do
    f.t = f.t - dt
    if f.t <= 0 then G.flames[i] = nil touch(i) end
  end
  for i, t in pairs(G.breaking) do
    local nt = t - dt
    if nt <= 0 then
      G.breaking[i] = nil
      G.grid[i] = FLOOR
      run.score = run.score + 10
      if G.items[i] then G.fresh[i] = 0.6 end
      touch(i)
    else
      G.breaking[i] = nt
    end
  end
  for i, t in pairs(G.fresh) do
    if t - dt <= 0 then G.fresh[i] = nil else G.fresh[i] = t - dt end
  end
end

-- ------------------------------------------------------------------ collisions
local function check_hits()
  local p = G.player
  local pc, pr = ent_tile(p)
  if p.alive then
    if G.flames[idx(pc, pr)] and p.shield <= 0 then kill_player("Caught in the blast") end
    for _, e in ipairs(G.foes) do
      if e.alive and abs(e.x - p.x) < 11 and abs(e.y - p.y) < 11 and p.shield <= 0 then
        kill_player(FOES[e.kind].name .. " got you")
      end
    end
  end
  for _, e in ipairs(G.foes) do
    if e.alive then
      local ec, er = ent_tile(e)
      local f = G.flames[idx(ec, er)]
      if f then
        e.alive = false
        local n = (G.blast_kills[f.blast] or 0) + 1
        G.blast_kills[f.blast] = n
        local pts = FOES[e.kind].score * (1 << (n - 1))
        run.score = run.score + pts
        popup(floor(e.x) + 8, floor(e.y), tostring(pts))
      end
    end
  end
  -- pick-ups and the gate
  if p.alive then
    local i = idx(pc, pr)
    local it = G.items[i]
    if it and it ~= "gate" and G.grid[i] == FLOOR then
      G.items[i] = nil
      touch(i)
      if it == "bomb" then run.bombs = min(8, run.bombs + 1)
      elseif it == "fire" then run.fire = min(8, run.fire + 1)
      elseif it == "speed" then run.speed = min(3, run.speed + 1)
      elseif it == "shield" then p.shield = 10 end
      ui.toast(PU_TEXT[it])
      flash(0x14F195, 0.3)
      run.score = run.score + 50
    elseif it == "gate" and G.open and G.grid[i] == FLOOR then
      local cx, cy = p.x + 8, p.y + 8
      if abs(cx - (pc * T + 8)) < 5 and abs(cy - (pr * T + 8)) < 5 then
        G.cleared = true
        G.clear_t = 0
      end
    end
  end
end

-- ------------------------------------------------------------------ stage lifecycle
local start_stage, show_title, show_help, show_over, show_win

local function free_stage()
  clear_popups()
  clear_overlay()
  G = nil
  hud = {}
  last_hud = {}
  ui.clear()
  leds_off()
end

local function spawn_foes(st)
  local spots = {}
  for r = 1, ROWS - 2 do
    for c = 1, COLS - 2 do
      if G.grid[idx(c, r)] == FLOOR and c + r >= 9 then spots[#spots + 1] = {c, r} end
    end
  end
  for _, kind in ipairs(st.foes) do
    if #spots == 0 then break end
    local k = random(#spots)
    local s = table.remove(spots, k)
    make_foe(kind, s[1], s[2])
  end
end

function start_stage()
  free_stage()
  local st = STAGES[run.stage]
  load_world(st.w)
  ui.bg(BG)
  G = {
    st = st, bombs = {}, flames = {}, breaking = {}, items = {}, fresh = {},
    drawn = {}, touched = {}, foes = {}, nbombs = 0, blast = 0, blast_kills = {},
    clock = 0, time = STAGE_TIME, open = false, cleared = false, gate_cool = 0,
    spawn_at_gate = 0, intro = 2.0,
  }
  local grid, deco, blocks = build_map(st)
  G.grid, G.deco = grid, deco
  -- hide the gate and the power-up under two different blocks
  if #blocks >= 2 then
    local a = table.remove(blocks, random(#blocks))
    local b = table.remove(blocks, random(#blocks))
    G.items[a] = "gate"
    G.items[b] = st.pu
    G.gate = a
    if #blocks >= 1 and run.stage >= 3 then
      -- a second, random bonus from stage 3 on
      local extra = {"bomb", "fire"}
      G.items[table.remove(blocks, random(#blocks))] = extra[random(#extra)]
    end
  end
  canvas = ui.canvas(MX, MY, COLS * T, ROWS * T, {scale = 1, color = BG})
  for i = 0, COLS * ROWS - 1 do draw_tile(i) end
  spawn_foes(st)
  G.player = make_player()
  hud_build(st)
  hud_update()
  -- intro card
  local W = A.worlds[st.w]
  local band = ui.rect(0, 70, ui.W, 74, {color = 0x0B0A14})
  overlay[#overlay + 1] = band
  overlay[#overlay + 1] = ui.gradient(0, 70, ui.W, 3)
  overlay[#overlay + 1] = ui.gradient(0, 141, ui.W, 3)
  local label = (run.epoch > 1 and ("EPOCH " .. run.epoch .. "  ") or "") .. "STAGE " .. stage_name(run.stage, 1)
  center_label(80, label, 32, "text")
  center_label(118, W.name .. "  -  find the Finality gate", 14, W.L)
  save.stage, save.epoch = run.stage, run.epoch
  persist()
  scene = "play"
end

local function stage_cleared()
  local bonus = max(0, floor(G.time)) * 10
  run.score = run.score + bonus
  if run.score > save.best then save.best = run.score end
  local band = ui.rect(0, 70, ui.W, 74, {color = 0x0B0A14})
  overlay[#overlay + 1] = band
  overlay[#overlay + 1] = ui.gradient(0, 70, ui.W, 3)
  overlay[#overlay + 1] = ui.gradient(0, 141, ui.W, 3)
  center_label(80, "FINALIZED!", 32, "green")
  center_label(118, "time bonus " .. bonus, 14, "text")
  award("s" .. run.stage, LAMP_STAGE, "stage " .. run.stage .. " cleared")
end

local function award_best()
  if run and run.score > run.best_at_start and run.score > 0 then
    award("best", LAMP_BEST, "new best score")
  end
end

local function next_stage()
  run.stage = run.stage + 1
  if run.stage > #STAGES then
    run.stage = 1
    run.epoch = run.epoch + 1
    if run.score > save.best then save.best = run.score end
    save.stage, save.epoch = 1, run.epoch
    persist()
    -- the epoch bonus is for playing all 8 stages, not for a CONTINUE at 4-2
    if run.from_stage == 1 then award("epoch", LAMP_EPOCH, "epoch finished") end
    award_best()
    show_win()
    return
  end
  start_stage()
end

local function lost_life()
  run.lives = run.lives - 1
  if run.lives <= 0 then
    if run.score > save.best then save.best = run.score end
    persist()
    award_best()
    show_over()
    return
  end
  start_stage()
end

-- ------------------------------------------------------------------ the play loop
local function update_leds(dt)
  if not has_led then return end
  if led_flash > 0 then
    led_flash = led_flash - dt
    for n = 1, 6 do led_put(n, led_flash_col) end
  else
    -- top LEDs: the fuse of the bomb closest to going off
    local tmin = nil
    for _, b in pairs(G.bombs) do
      if not tmin or b.t < tmin then tmin = b.t end
    end
    local lit = tmin and math.ceil(tmin / FUSE * 6) or 0
    for n = 1, 6 do
      if n <= lit then led_put(n, tmin < 0.8 and 0xFF3020 or 0xFF8A3D)
      elseif G.open then led_put(n, (floor(G.clock * 6) % 6 + 1 == n) and 0x14F195 or 0)
      else led_put(n, 0) end
    end
  end
  led_put(7, run.lives >= 1 and 0x14F195 or 0x300000)
  led_put(8, run.lives >= 2 and 0x14F195 or 0x300000)
end

local function play_tick(dt)
  G.clock = G.clock + dt
  if G.intro > 0 then
    G.intro = G.intro - dt
    if G.intro <= 0 then clear_overlay() end
    update_leds(dt)
    return
  end
  if G.cleared then
    if not G.clear_shown then G.clear_shown = true stage_cleared() end
    G.clear_t = G.clear_t + dt
    for n = 1, 8 do
      if has_led then led_put(n, (floor(G.clock * 12) % 8 + 1 == n) and 0x14F195 or 0x002010) end
    end
    if G.clear_t > 2.6 then next_stage() end
    return
  end
  if G.player.alive then
    G.time = G.time - dt
    if G.time <= 0 then kill_player("Slot missed: time out") end
  end
  update_player(dt)
  update_bombs(dt)
  for _, e in ipairs(G.foes) do update_foe(e, dt) end
  check_hits()
  -- drop the foes that finished dying
  local alive = 0
  for k = #G.foes, 1, -1 do
    local e = G.foes[k]
    if e.gone then table.remove(G.foes, k) elseif e.alive then alive = alive + 1 end
  end
  if alive == 0 and not G.open then
    G.open = true
    touch(G.gate)
    ui.toast("All clear: the Finality gate is open")
  end
  if G.gate_cool > 0 then G.gate_cool = G.gate_cool - dt end
  if G.spawn_at_gate > 0 and not G.flames[G.gate] then
    local c, r = G.gate % COLS, G.gate // COLS
    for _ = 1, G.spawn_at_gate do make_foe("fud", c, r) end
    G.spawn_at_gate = 0
    G.open = false
    touch(G.gate)
    ui.toast("You hit the gate: FUD spreads!")
  end
  if not G.player.alive and G.player.dying > 1.6 then
    lost_life()
    return
  end
  redraw_dirty()
  update_popups(dt)
  hud_update()
  update_leds(dt)
end

local paused = false
local function set_pause(on)
  paused = on
  if on then
    local band = ui.rect(0, 70, ui.W, 74, {color = 0x0B0A14})
    overlay[#overlay + 1] = band
    overlay[#overlay + 1] = ui.gradient(0, 70, ui.W, 3)
    overlay[#overlay + 1] = ui.gradient(0, 141, ui.W, 3)
    center_label(82, "PAUSED", 32, "text")
    center_label(120, "SELECT resume    CANCEL quit to menu", 12, "dim")
    leds_off()
  else
    clear_overlay()
  end
end

-- ------------------------------------------------------------------ title, help, game over
local menu = {}
local menu_sel = 1
local title_anim = {}

local function menu_draw()
  for n, item in ipairs(menu) do
    local on = n == menu_sel
    item.l:text((on and "> " or "  ") .. item.text .. (on and " <" or "  "))
    item.l:color(on and "green" or "dim")
  end
end

function show_title()
  free_stage()
  G = nil
  scene = "title"
  paused = false
  load_world(loaded_world == 0 and 1 or loaded_world)
  ui.clear()
  ui.bg(BG)
  -- a strip of map behind the title
  local c = ui.canvas(0, 0, 160, 109, {scale = 2, color = BG})
  for x = 0, 9 do
    c:image(IMG.wall, x * 16, 0)
    c:image(IMG.wall, x * 16, 93)
  end
  for x = 0, 9 do
    for y = 1, 4 do c:image(IMG.floor, x * 16, y * 16 - 3) end
  end
  ui.rect(0, 26, ui.W, 158, {color = BG})
  ui.gradient(0, 26, ui.W, 2)
  ui.gradient(0, 182, ui.W, 2)
  ui.image(48, 36, IMG.title, {scale = 4})
  ui.label(0, 76, "a Solana badge game", {size = 12, color = "dim", w = ui.W, align = "center"})
  title_anim.hero = ui.image(20, 112, IMG.hero_r0, {scale = 3})
  title_anim.bomb = ui.image(256, 112, IMG.bomb1, {scale = 3})
  title_anim.t = 0
  menu = {}
  local items = {{id = "new", text = "NEW GAME"}}
  if save.stage > 1 or save.epoch > 1 then
    items[#items + 1] = {id = "cont", text = "CONTINUE " .. stage_name(save.stage, save.epoch)}
  end
  items[#items + 1] = {id = "help", text = "HOW TO PLAY"}
  for n, it in ipairs(items) do
    it.l = ui.label(0, 96 + (n - 1) * 22, "", {size = 14, w = ui.W, align = "center"})
    menu[n] = it
  end
  menu_sel = 1
  menu_draw()
  ui.label(0, 166, "BEST " .. save.best, {size = 12, color = "yellow", w = ui.W, align = "center"})
  ui.hint("UP/DOWN choose   SELECT start   CANCEL exit")
end

local function title_tick(dt)
  title_anim.t = title_anim.t + dt
  local t = title_anim.t
  local seq = {1, 0, 2, 0}
  title_anim.hero:set(IMG["hero_r" .. seq[floor(t * 6) % 4 + 1]])
  title_anim.bomb:set(IMG["bomb" .. (floor(t * 4) % 3 + 1)])
  if has_led then
    for n = 1, 6 do
      local ph = (floor(t * 8) + n) % 6
      led_put(n, ph < 2 and 0x9945FF or ph < 4 and 0x3FD8E8 or 0x14F195)
    end
    led_put(7, 0) led_put(8, 0)
  end
end

local function new_run(stage, epoch)
  run = {stage = stage, epoch = epoch, score = 0, lives = 3, bombs = 1, fire = 1, speed = 0,
    best_at_start = save.best, from_stage = stage}
  if stage > 1 or epoch > 1 then
    -- a continue starts with a little firepower for where it lands
    run.bombs = min(4, 1 + floor((stage - 1) / 2))
    run.fire = min(4, 1 + floor((stage - 1) / 2))
  end
  start_stage()
end

function show_help()
