    ui.label(42, y + 16, f[3], {size = 12, color = "dim"})
  end
  local pus = {
    {"pu_bomb1", "+1 BOMB"}, {"pu_fire1", "+1 RANGE"},
    {"pu_speed1", "IBRL speed"}, {"pu_shield1", "SHIELD 10s"},
  }
  for n, f in ipairs(pus) do
    local y = 36 + (n - 1) * 30
    ui.image(176, y, IMG[f[1]], {scale = 2})
