local function end_card(title, color, line1, line2)
  free_stage()
  ui.clear()
  ui.bg(BG)
  ui.gradient(0, 40, ui.W, 3)
  ui.label(0, 56, title, {size = 32, color = color, w = ui.W, align = "center"})
  ui.label(0, 100, line1, {size = 14, color = "text", w = ui.W, align = "center"})
  ui.label(0, 122, line2, {size = 14, color = "dim", w = ui.W, align = "center"})
